-- 牌图文件需在运行目录 uploads/cards/ 下（已复制到 server/uploads/cards/）。
-- 中文牌名以代码牌组为准：Excel「皇后」→ 女皇，「隐士」→ 隐者。
-- 备用问题文档写 30 条，正文实际 36 条（6 类 × 6），按文档全量入库。

BEGIN;

CREATE TABLE IF NOT EXISTS preset_questions (
  question_id TEXT PRIMARY KEY,
  pool TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  enabled BOOLEAN NOT NULL DEFAULT TRUE
);

DELETE FROM preset_questions WHERE question_id LIKE 'featured_%' OR question_id LIKE 'backup_%';

